    'FixFileEncodingIssuesDesc'           => 'Reparer uploadfiler med problemer med tegnkodning. Kun synlig når det er nødvendigt.',
    'DatabaseUpgradeDesc'                 => 'Udløs manuelt SimpleRisk-databaseopgraderingsrutinen.',

