    'AnyType' => 'Enhver type',
    'AnyStatus' => 'Enhver status',
    'SelectAllN' => 'Vælg alle {n}',
    'Classification' => 'Klassifikation',
    'Placement' => 'Placering',
    'OwnershipAndMaturity' => 'Ejerskab og modenhed',
    'MappingsAndGuidance' => 'Kortlægninger og vejledning',
